// The change text document notification's parameters.
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash)]
pub struct DidChangeTextDocumentParams {
    // The document that did change. The version number points
    // to the version after all provided content changes have
    // been applied.
    pub text_document: VersionedTextDocumentIdentifier,

    // The actual content changes. The content changes describe single state changes
    // to the document. So if there are two content changes c1 (at array index 0) and
    // c2 (at array index 1) for a document in state S then c1 moves the document from
    // S to S' and c2 from S' to S''. So c1 is computed on the state S and c2 is computed
    // on the state S'.
    //
    // To mirror the content of a document using change events use the following approach:
    // - start with the same initial content
    // - apply the 'textDocument/didChange' notifications in the order you receive them.
    // - apply the `TextDocumentContentChangeEvent`s in a single notification in the order
    //  you receive them.
    pub content_changes: Vec<TextDocumentContentChangePartialOrWholeDocument>,
}



impl IsZero for DidChangeTextDocumentParams {
    // PORT: Go reflect.Value.IsZero (omitzero).
    fn is_zero(&self) -> bool {
        self.text_document.is_zero() && self.content_changes.is_empty()
    }
}

